    ayahs: [
      { number: 1, arabic: "لَا أُقْسِمُ بِهَٰذَا الْبَلَدِ", translation: "I swear by this city [i.e., Makkah]" },
      { number: 2, arabic: "وَأَنتَ حِلٌّ بِهَٰذَا الْبَلَدِ", translation: "And you, [O Muḥammad], are free of restriction in this city" },
      { number: 3, arabic: "وَوَالِدٍ وَمَا وَلَدَ", translation: "And [by] the father and that which was born [of him]," },
      { number: 4, arabic: "لَقَدْ خَلَقْنَا الْإِنسَانَ فِي كَبَدٍ", translation: "We have certainly created man into hardship." },
      { number: 5, arabic: "أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌ", translation: "Does he think that never will anyone overcome him?" },
      { number: 6, arabic: "يَقُولُ أَهْلَكْتُ مَالًا لُّبَدًا", translation: "He says, \"I have spent wealth in abundance.\"" },
      { number: 7, arabic: "أَيَحْسَبُ أَن لَّمْ يَرَهُ أَحَدٌ", translation: "Does he think that no one has seen him?" },
      { number: 8, arabic: "أَلَمْ نَجْعَل لَّهُ عَيْنَيْنِ", translation: "Have We not made for him two eyes?" },
      { number: 9, arabic: "وَلِسَانًا وَشَفَتَيْنِ", translation: "And a tongue and two lips?" },
      { number: 10, arabic: "وَهَدَيْنَاهُ النَّجْدَيْنِ", translation: "And have shown him the two ways?" },
      { number: 11, arabic: "فَلَا اقْتَحَمَ الْعَقَبَةَ", translation: "But he has not broken through the difficult pass." },
      { number: 12, arabic: "وَمَا أَدْرَاكَ مَا الْعَقَبَةُ", translation: "And what can make you know what is [breaking through] the difficult pass?" },
      { number: 13, arabic: "فَكُّ رَقَبَةٍ", translation: "It is the freeing of a slave" },
      { number: 14, arabic: "أَوْ إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ", translation: "Or feeding on a day of severe hunger" },
      { number: 15, arabic: "يَتِيمًا ذَا مَقْرَبَةٍ", translation: "An orphan of near relationship" },
      { number: 16, arabic: "أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ", translation: "Or a needy person in misery" },
      { number: 17, arabic: "ثُمَّ كَانَ مِنَ الَّذِينَ آمَنُوا وَتَوَاصَوْا بِالصَّبْرِ وَتَوَاصَوْا بِالْمَرْحَمَةِ", translation: "And then being among those who believed and advised one another to patience and advised one another to compassion." },
      { number: 18, arabic: "أُولَٰئِكَ أَصْحَابُ الْمَيْمَنَةِ", translation: "Those are the companions of the right." },
      { number: 19, arabic: "وَالَّذِينَ كَفَرُوا بِآيَاتِنَا هُمْ أَصْحَابُ الْمَشْأَمَةِ", translation: "But they who disbelieved in Our signs - those are the companions of the left." },
      { number: 20, arabic: "عَلَيْهِمْ نَارٌ مُّؤْصَدَةٌ", translation: "Over them will be fire closed in." },
    ],
